INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62105240', 62105240, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Pemutakhiran Peta PBB Wilayah 2', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Timur, Sidoarjo (Kab.)', 48000000, 'January 2026', 'APBD', 1, 1, '1 Tahun', 'Ruang lingkup pekerjaan yang dimaksud dalam Kerangka Acuan Kerja (KAK) adalah: a. Tenaga Ahli berkoordinasi dengan Tim Teknis BPPD Kabupaten Sidoarjo dalam kebutuhan data primer dan sekunder pekerjaan, b. Melakukan orientasi dan pengecekan awal pada data/file peta masing-masing desa/kelurahan yang termasuk dalam pekerjaan ini c. Melakukan proses sinkron awal antara data/file peta dengan peta online google/bing d. Pengecekan sistem koordinat, proyeksi dan datum peta e. Melakukan pengaturan dan aktifasi tools pada aplikasi/software peta (arcgis) f. Melakukan proses pekerjaan yang dibutuhkan dan disesuaikan dengan hasil orientasi dan sinkronisasi diatas berupa : i. penyesuaian/geser obyek/bidang dan/atau ii. penggambaran ulang obyek/bidang peta g. Melakukan pengecekan dan/atau input NOP pada obyek/bidang yang telah melalui proses diatas h. Melakukan backup data/file peta per desa/kelurahan. i. Membuat laporan pekerjaan', 'a. Daftar personil yang harus dipenuhi : PosisiPenugasan Kualifikasi Tingkat Pendidikan Minimal Program Studi Keahlian Jumlah Personel Tenaga Pendukung S1 Geodesi/Geomatika/ Perencanaan Wilayah Kota Pemetaan berbasis Geografic Information System 1 Orang Dengan persyaratan : 1. memiliki komptensi sesuai bidang dipersyaratkan dibuktikan dengan ijazah jenjang pendidikan Strata 1 dengan program studi geodesi/geomatika/Perencanaan wilayah kota 2. Memiliki sertifikat keahlian/teknis, dan/atau sertifikat pelatihan terkait ahli pemetaan berbasis GIS (Geografic Information System) 3. memiliki pengalaman minimal 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik dilingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak 4. memiliki pengalaman pekerjaan yang relevan minimal 4 (empat) tahun b. Rincian tugas personil : 1. Tenaga Ahli Tugasnya adalah sebagai berikut : a) Tenaga Ahli berkoordinasi dengan Tim Teknis BPPD Kabupaten Sidoarjo dalam kebutuhan data primer dan sekunder pekerjaan,` b) Melakukan orientasi dan pengecekan awal pada data/file peta masing-masing desa/kelurahan yang termasuk dalam pekerjaan ini c) Melakukan proses sinkron awal antara data/file peta dengan peta online google/bing d) Pengecekan sistem koordinat, proyeksi dan datum peta pada masing-masing data/file peta e) Melakukan pengaturan dan aktifasi tools pada aplikasi/software peta (arcgis) f) Melakukan proses pekerjaan yang dibutuhkan dan disesuaikan dengan hasil orientasi dan sinkronisasi diatas berupa : i.penyesuaian/geser obyek/bidang dan/atau ii.penggambaran ulang obyek/bidang peta g) Melakukan pengecekan dan/atau input NOP pada obyek/bidang yang telah melalui proses diatas h) Melakukan backup data/file peta per desa/kelurahan. i) i.Membuat laporan pekerjaan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 200235);
