INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64297029', 64297029, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KOTA JAMBI', 'Belanja oli pelumas dan BBM genset', 'Barang', 'Pengadaan Langsung', 'Jambi, Jambi (Kota)', 6000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 TAHUN', 'Belanja oli pelumas dan BBM genset', 'Ruang lingkup kegiatan meliputi belanja oli pelumas dan bahan bakar minyak (BBM) untuk genset, guna mendukung kelancaran operasional peralatan genset sebagai sumber listrik cadangan. Oli pelumas yang disediakan harus sesuai dengan spesifikasi teknis genset, menjamin kinerja mesin yang optimal, sedangkan BBM harus memenuhi standar mutu dan keamanan. Seluruh barang harus dalam kondisi baru, layak pakai, dan tersedia sesuai kebutuhan operasional. Pelaksanaan kegiatan dilaksanakan secara tertib administrasi dan dapat dipertanggungjawabkan, dengan berpedoman pada prinsip efisien, efektif, transparan, dan akuntabel, serta sesuai dengan ketentuan peraturan perundang-undangan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 202261);
