INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62109540', 62109540, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR LABORATORIUM KESEHATAN MASYARAKAT MAKASSAR', 'Pengadaan Jasa Outsourcing Cleaning Service (Sumber Dana RM) BBLKM Makassar TA.2026', 'Jasa Lainnya', 'E-Purchasing', 'Sulawesi Selatan, Makassar (Kota)', 799200000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 144, OB, @ 5550000 )', '1. Jasa Outsourcing Cleaning Service 12 org 12 Bulan ( 144, OB, @ 5550000 );', 'Kualifikasi Teknis : 1. Memiliki izin usaha Jasa Kebersihan (KLBI 81210) dan NIB 2. Memiliki Pengalaman Kerja di bidang kebersihan Kualifikasi Tenaga Kerja : 1. Pendidikan Minimal SLTA/SMA/SMK 2. Sehat jasmani dan rohani (Surat Keterangan Sehat) 3. Bebas Narkoba (Surat Keterangan Bebas Narkoba Terbaru) Cakupan dan Standar Pekerjaan: 1. Menyapu dan mengepel, membersihkan toilet, kaca, taman, halaman, merawat tanaman (sesuai kebutuhan) 2. Penanganan Area Khusus (gudang, ruang instalasi, dll) 3. Pelaksanaan Servis Excelent, pemeliharaan kebersihan berkelanjutan (misal: lantai bersih terus menerus) 4. membantu kegiatan lain (sesuai Kebutuhan) Peralatan dan Bahan Kimia: 1. Wajib menyediakan peralatan lengkap (Sapu, pel, sikat, dll) (dan bahan kimia pembersih yang aman dan efektif) Manajemen Operasional: 1. Penyusunan dan Penerapan SOP kebersihan yang jelas 2. Pengawasan : jadwal kerja, pengawasan rutin, dan evaluasi hasil kerja.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 202721);
