INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63707553', 63707553, 'analyze_legacy', 'Badan Gizi Nasional', 'central', 'BADAN GIZI NASIONAL', 'Paket Pengadaan Sewa Kendaraan Roda Empat Badan Gizi Nasional Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 3240000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '(5 unit x 4 pimp x 12 bulan)', 'Dalam rangka mendukung kelancaran pelaksanaan tugas dan fungsi Wakil Kepala Badan Gizi Nasional Bidang Pengembangan Organisasi dan Hubungan Kelembagaan, diperlukan dukungan sarana transportasi yang andal, aman, dan representatif. Intensitas kegiatan koordinasi lintas kementerian/lembaga, pemerintah daerah, mitra internasional, serta pemangku kepentingan lainnya menuntut ketersediaan kendaraan operasional yang siap pakai, berstandar kenyamanan tinggi, serta memenuhi aspek keselamatan dan efisiensi. Sehubungan dengan hal tersebut, Badan Gizi Nasional memandang perlu untuk melaksanakan kegiatan pengadaan jasa sewa kendaraan operasional guna menjamin kontinuitas mobilitas pimpinan dan sekretariat dalam menjalankan tugas kedinasan secara efektif dan efisien.', 'Spesifikasi di KAK', 3240000000, 'absurd', 'Penyewaan 5 kendaraan roda empat untuk 4 pimpinan selama 12 bulan dengan total anggaran sangat besar menunjukkan fasilitas yang berlebihan dan berpotensi tidak proporsional untuk dukungan tugas kedinasan. Frasa \'representatif\' dan \'standar kenyamanan tinggi\' memperkuat indikasi penggunaan anggaran untuk fasilitas pimpinan yang mewah atau berlebihan.', NULL, NULL, 4, 1, 1, 1, 1, 204804);
