INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62114254', 62114254, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA KETAPANG 04', 'PENGADAAN JASA KONSULTANSI POS BANTUAN HUKUM PENGADILAN AGAMA KETAPANG', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Kalimantan Barat, Ketapang (Kab.)', 70000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '700 Orang', '1. Pelayanan Posbakum (Front Office Service): - Penerimaan dan Pendaftaran Pencari Keadilan - Pemberian Informasi dan Konsultasi Hukum Awal - Penyusunan dan Pengisian Data 2. Penyediaan Dokumen Hukum: - Pembuatan Draft Gugatan/Permohonan/Jawaban Awal - Penyediaan Formulir dan Contoh Dokumen 3. Pemberian Layanan Rekomendasi (Rujukan): - Verifikasi Syarat Bantuan Hukum - Penerbitan Surat Keterangan/Rekomendasi 4. Pelaporan dan Evaluasi: - Penyusunan Laporan Bulanan/Triwulanan - Partisipasi dalam Evaluasi', '1. Spesifikasi Teknis Layanan (Output dan Kuantitas): - Waktu Pelayanan: Layanan wajib dibuka setiap hari kerja pengadilan (Senin s.d. Jum\'at) - Jam Operasional: Minimal jam 08.00 WIB hingga jam 16.00 WIB (atau sesuai jam kerja kantor pengadilan) - Kuantitas Kasus: Mampu melayani rata-rata 5 - 10 pencari keadilan per hari (tergantung volume pengadilan) - Output Utama (Layanan): Menyediakan layanan konsultasi hukum, informasi prosedur, dan draft gugatan/permohonan awal. - Output Wajib (Rujukan): Menerbitkan surat keterangan posbakum sebagai rujukan ke LBH terakreditasi bagi pencari keadilan yang memenuhi syarat. 2. Spesifikasi Tenaga Ahli (Kualifikasi SDM): - Koordinator Lapangan (minimal 1 orang): Dengan kualifikasi diutamakan berprofesi sebagai Advokat yang terdaftar pada Organisasi Advokat resmi atau Sarjana Hukum berpengalaman (minimal 3 tahun). - Tenaga Konsultan/Paralegal (minimal 1-2 orang): Dengan kualifikasi Sarjana Hukum atau mahasiswa hukum tingkat akhir, atau paralegal bersertifikat/terlatih. 3. Spesifikasi Administrasi dan Pelaporan: - Sistem Pencatatan: Wajib memiliki dan menggunakan buku register posbakum - Laporan Periodik: Wajib menyampaikan laporan bulanan dan laporan akhir kegiatan kepada pengadilan 4. Spesifikasi Sarana dan Prasarana: - Ketersediaan Petugas: Petugas harus menggunakan ID card atau pakaian seragam - Dokumentasi: Menyediakan hardcopy dan softcopy semua formulir standar, contoh surat gugatan, dan lembar informasi hukum yang relevan - Kerahasiaan: Wajib menjaga kerahasiaan data dan informasi yang diberikan oleh pencari keadilan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 208967);
