INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62114398', 62114398, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Statistika dan Analisis Kewilayahan Penyusunan Rekomendasi Kebijakan Atas Program Prioritas Nasional Untuk Ekonomi Regional dan Pemerataan Pembangunan Nasional Unit Staf Ahli Menteri Bidang Pemerataan Pembangunan Regional', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 108000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Melakukan pengumpulan, pengolahan, dan verifikasi data statistik dan spasial yang relevan dengan isu pemerataan pembangunan regional, baik yang bersumber dari BPS, K/L, maupun data internal Bappenas. 2. Melakukan analisis statistik deskriptif dan inferensial, termasuk pengukuran ketimpangan pembangunan antarwilayah. 3. Melakukan analisis spasial berbasis data menggunakan perangkat lunak analisis seperti R, Python, atau Tableau, untuk menggambarkan pola kewilayahan, keterkaitan antarindikator, serta tren pembangunan antarprovinsi/kabupaten.', '4. Menyusun model statistik dan proyeksi (forecasting) terhadap indikator pembangunan wilayah guna memperkirakan arah dan potensi ketimpangan pembangunan di masa mendatang. 5. Mengembangkan dan memperbarui dashboard interaktif atau visualisasi data kewilayahan dengan memanfaatkan Tableau atau library visualisasi Python/R untuk keperluan monitoring dan komunikasi hasil analisis. 6. Menyusun laporan analisis tematik terkait isu strategis pemerataan pembangunan regional, termasuk rekomendasi kebijakan yang dapat ditindaklanjuti', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 209635);
